#!/usr/bin/env python3
"""Revert a resharded directory (produced by compress.py) back to the
original file structure, in-place.

Usage:  python /app/decompress.py <resharded_dir>
"""
import json
import os
import shutil
import sys
import tarfile
import tempfile


class ChunkReader:
    """A read-only file object that concatenates a list of chunk files so a
    streaming tar reader can consume them as one stream."""

    def __init__(self, paths):
        self.paths = list(paths)
        self.idx = 0
        self.f = None

    def _open_next(self):
        if self.f is not None:
            self.f.close()
            self.f = None
        if self.idx < len(self.paths):
            self.f = open(self.paths[self.idx], "rb")
            self.idx += 1
            return True
        return False

    def read(self, n=-1):
        if self.f is None and not self._open_next():
            return b""
        if n is None or n < 0:
            out = []
            while True:
                d = self.f.read() if self.f else b""
                if d:
                    out.append(d)
                if not self._open_next():
                    break
            return b"".join(out)
        out = b""
        while len(out) < n:
            d = self.f.read(n - len(out)) if self.f else b""
            if d:
                out += d
            elif not self._open_next():
                break
        return out

    def close(self):
        if self.f is not None:
            self.f.close()
            self.f = None


def _extractall(tar, path):
    # filter='data' (py>=3.12) strips risky metadata; fall back for older.
    try:
        tar.extractall(path, filter="data")
    except TypeError:
        tar.extractall(path)


def main():
    if len(sys.argv) != 2:
        sys.stderr.write("usage: python decompress.py <resharded_dir>\n")
        return 2
    resh = os.path.abspath(sys.argv[1])
    manifest_path = os.path.join(resh, "manifest.json")
    if not os.path.isfile(manifest_path):
        sys.stderr.write(f"manifest.json not found in {resh}\n")
        return 2
    with open(manifest_path) as mf:
        manifest = json.load(mf)

    chunk_paths = [os.path.join(resh, p) for p in manifest["chunks"]]

    # Extract into a temp dir (sibling), then swap contents in-place.
    parent = os.path.dirname(resh) or "."
    tmp_extract = tempfile.mkdtemp(prefix=".reshard_extract_", dir=parent)
    try:
        reader = ChunkReader(chunk_paths)
        try:
            with tarfile.open(fileobj=reader, mode="r|gz") as tar:
                _extractall(tar, tmp_extract)
        finally:
            reader.close()

        # Remove resharded artifacts from the target directory.
        os.remove(manifest_path)
        shards_dir = os.path.join(resh, "shards")
        if os.path.isdir(shards_dir):
            shutil.rmtree(shards_dir)

        # Move reconstructed contents into place.
        for name in os.listdir(tmp_extract):
            src = os.path.join(tmp_extract, name)
            dst = os.path.join(resh, name)
            if os.path.exists(dst):
                if os.path.isdir(dst) and not os.path.islink(dst):
                    shutil.rmtree(dst)
                else:
                    os.remove(dst)
            shutil.move(src, dst)
    finally:
        shutil.rmtree(tmp_extract, ignore_errors=True)

    print(f"restored original structure in {resh}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
